# Start of the Movement phase: no token is dim.
var toks = []
for tn in tree.root.get_node("Main/BoardRoot/TokenLayer").get_children():
	if tn.is_queued_for_deletion():
		continue
	if tn.has_meta("unit_id") and "is_exhausted_this_phase" in tn:
		toks.append(tn)
	else:
		for tg in tn.get_children():
			if tg.has_meta("unit_id") and "is_exhausted_this_phase" in tg:
				toks.append(tg)
var dim_ids = []
var bad = []
var n_dim = 0
var n_lit = 0
for t in toks:
	var uid = str(t.get_meta("unit_id"))
	var c = t.modulate
	if uid in dim_ids:
		if absf(c.r - 0.6) <= 0.02 and absf(c.g - 0.6) <= 0.02 and absf(c.b - 0.6) <= 0.02 and absf(c.a - 1.0) <= 0.02 and t.is_exhausted_this_phase == true:
			n_dim += 1
		else:
			bad.append("%s %s/%s (want dim)" % [uid, c.to_html(true), str(t.is_exhausted_this_phase)])
	else:
		if absf(c.r - 1.0) <= 0.02 and absf(c.g - 1.0) <= 0.02 and absf(c.b - 1.0) <= 0.02 and absf(c.a - 1.0) <= 0.02 and t.is_exhausted_this_phase == false:
			n_lit += 1
		else:
			bad.append("%s %s/%s (want lit)" % [uid, c.to_html(true), str(t.is_exhausted_this_phase)])
if not bad.is_empty():
	return ", ".join(bad)
if n_dim != 0 or n_lit != 25:
	return "counted %d dim / %d lit tokens" % [n_dim, n_lit]
return "ok"

