var bad = []
var n = 0
for c in r.get_node("Scroll/Cards").get_children():
	var uid = str(c.get_meta("unit_id", ""))
	var m = c.modulate
	if uid in dim_ids:
		var sb = c.get_theme_stylebox("panel")
		if not (r.is_card_exhausted(uid) and absf(m.r - 0.6) <= 0.02 and absf(m.g - 0.6) <= 0.02 and absf(m.b - 0.6) <= 0.02 and absf(m.a - 1.0) <= 0.02 and c.has_theme_stylebox_override("panel") and sb is StyleBoxFlat and sb.bg_color.v < 0.1):
			bad.append(uid + " card not dim")
	else:
		if r.is_card_exhausted(uid) or not (absf(m.r - 1.0) <= 0.02 and absf(m.g - 1.0) <= 0.02 and absf(m.b - 1.0) <= 0.02 and absf(m.a - 1.0) <= 0.02) or c.has_theme_stylebox_override("panel"):
			bad.append(uid + " card dim")
	n += 1
if n != GameState.state.units.size():
	return "%d cards for %d units" % [n, GameState.state.units.size()]
return "ok" if bad.is_empty() else ", ".join(bad)

