# Tier B support, T08 rings on a dimmed token: sample the live frame on each
# ring's mid-line (32 angles). On the two acted tokens the slot ring must read
# 0.6 x its slot colour and the faction band 0.6 x the unit colour (the dim
# multiplies both), and the two dimmed colours stay far apart. On an un-acted
# Custodian Guard token the rings read their full colours (control).
# Measured: Blade Champion slot 28/32 faction 24/32 sep 0.61, Shield-Captain
# 32/32 24/32 0.54, Custodian Guard (lit) 29/32 26/32 0.96. Undimmed, the two
# acted tokens would score ~0 against the 0.6 colours.
var m = tree.root.get_node("Main")
var img = tree.root.get_texture().get_image()
var zoom = m.view_zoom
var toks = []
for tn in tree.root.get_node("Main/BoardRoot/TokenLayer").get_children():
	if tn.is_queued_for_deletion():
		continue
	if tn.has_meta("unit_id") and "is_exhausted_this_phase" in tn:
		toks.append(tn)
	else:
		for tg in tn.get_children():
			if tg.has_meta("unit_id") and "is_exhausted_this_phase" in tg:
				toks.append(tg)
var res = []
var bad = []
for t in toks:
	var uid = str(t.get_meta("unit_id"))
	var want_dim = uid == "U_BLADE_CHAMPION_A" or uid == "U_SHIELD_CAPTAIN_A"
	if not want_dim and not (uid == "U_CUSTODIAN_GUARD_B" and str(t.get_meta("model_id")) == "m1"):
		continue
	var k = 0.6 if want_dim else 1.0
	var g = t.t08_ring_geometry()
	var c0 = t.get_global_transform_with_canvas().origin
	var fcol = t.get_node("FactionRing").modulate
	var scol = t.get_node("SlotRing").modulate
	var fk = Color(fcol.r * k, fcol.g * k, fcol.b * k)
	var sk = Color(scol.r * k, scol.g * k, scol.b * k)
	var hs = 0
	var hf = 0
	for i in range(32):
		var a = TAU * float(i) / 32.0
		var d = Vector2(cos(a), sin(a))
		var ps = c0 + d * float(g["slot_mid"]) * zoom
		var pf = c0 + d * float(g["faction_mid"]) * zoom
		var cs = img.get_pixel(int(round(ps.x)), int(round(ps.y)))
		var cf = img.get_pixel(int(round(pf.x)), int(round(pf.y)))
		if absf(cs.r - sk.r) < 0.05 and absf(cs.g - sk.g) < 0.05 and absf(cs.b - sk.b) < 0.05:
			hs += 1
		if absf(cf.r - fk.r) < 0.05 and absf(cf.g - fk.g) < 0.05 and absf(cf.b - fk.b) < 0.05:
			hf += 1
	var sep = Vector3(sk.r - fk.r, sk.g - fk.g, sk.b - fk.b).length()
	res.append("%s k%.1f slot %d/32 faction %d/32 sep %.2f" % [uid, k, hs, hf, sep])
	if hs < 24 or hf < 18 or sep < 0.25:
		bad.append(res[-1])
if res.size() != 3:
	return "sampled %d tokens, want 3: %s" % [res.size(), str(res)]
return "ok" if bad.is_empty() else ", ".join(bad)

var p = PhaseManager.get_current_phase_instance()
for i in range(4):
